def magic_square_test(square):
    n = len(square)
    magic_sum = sum(square[0])  # Sum of the first row
    for row in square:
        if sum(row) != magic_sum:
            return False
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != magic_sum:
            return False
    if sum(square[i][i] for i in range(n)) != magic_sum or sum(square[i][n-1-i] for i in range(n)) != magic_sum:
        return False
    return True
