def magic_square_test(square):
    expected_sum = sum(square[0])
    for row in square:
        if sum(row) != expected_sum:
            return False
    for col in range(len(square[0])):
        if sum([row[col] for row in square]) != expected_sum:
            return False
    if sum([square[i][i] for i in range(len(square))]) != expected_sum:
        return False
    if sum([square[i][len(square)-i-1] for i in range(len(square))]) != expected_sum:
        return False
    return True
