def magic_square_order(n):
    return ((n - 1) * 2 + 1) ** 2

def is_valid_magic_square(matrix):
    order = magic_square_order(len(matrix))
    row_sum = [0] * (order + 1)
    col_sum = [0] * (order + 1)
    diag_sum = 0
    diag_sum_reverse = 0

    for i in range(len(matrix)):
        for j in range(len(matrix)):
            value = matrix[i][j]
            if value < 1 or value > order:
                return False
            row_sum[i + 1] += value
            col_sum[j + 1] += value
            if i == j:
                diag_sum += value
            if i + j == order:
                diag_sum_reverse += value

    return row_sum == col_sum == [order * (x + 1) for x in range(1, len(row_sum))] and diag_sum == diag_sum_reverse == order * len(matrix)

def magic_square_test(matrix):
    return is_valid_magic_square(matrix)
