            x = (x * x) % p
            y //= 2
        return res
    def modinv(x, p):
        return modpow(x, p - 2, p)
    num = 1
    for i in range(1, r + 1):
        num = (num * (n - i + 1)) % p
    den = 1
    for i in range(1, r + 1):
        den = (den * i) % p
    return (num * modinv(den, p)) % p
