def nCr_mod_p(n, r, p):
    def factorial_mod_p(n, p):
        res = 1
        for i in range(1, n + 1):
            res = (res * i) % p
        return res

    def inverse_mod_p(a, p):
        return pow(a, p - 2, p)

    n_fact = factorial_mod_p(n, p)
    r_fact = factorial_mod_p(r, p)
    n_r_fact = factorial_mod_p(n - r, p)

    return (n_fact * inverse_mod_p(r_fact, p) * inverse_mod_p(n_r_fact, p)) % p
