def nCr_mod_p(n, r, p):
    def factorial_mod_p(n, p):
        fact = 1
        for i in range(1, n+1):
            fact = (fact * i) % p
        return fact

    def modular_inverse(a, p):
        return pow(a, p-2, p)

    if r > n - r:
        r = n - r

    numerator = factorial_mod_p(n, p)
    denominator = factorial_mod_p(r, p) * factorial_mod_p(n-r, p) % p

    return (numerator * modular_inverse(denominator, p)) % p
