    visited = set()

    for i in range(n):
        for j in range(n):
            queue.append((i, j, [grid[i][j]]))
            visited.add((i, j, tuple([grid[i][j]])))

    while queue:
        x, y, path = queue.popleft()

        if len(path) == k:
            if path < min_path:
                min_path = path
            continue

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                state = (nx, ny, tuple(new_path))
                if state not in visited:
                    queue.append((nx, ny, new_path))
                    visited.add(state)

    return min_path

